query environments($after: String, $before: String, $first: Int, $isEphemeral: Boolean, $last: Int, $projectId: String!) {
  environments(after: $after, before: $before, first: $first, isEphemeral: $isEphemeral, last: $last, projectId: $projectId) {
    edges {
      cursor
      node {
        createdAt
        deletedAt
        id
        isEphemeral
        name
        projectId
        updatedAt
        volumeInstances(first: 200) {
          edges {
            node {
              createdAt
              currentSizeMB
              deletedAt
              environmentId
              id
              isPendingDeletion
              mountPath
              region
              serviceId
              sizeMB
              state
              volume {
                createdAt
                id
                name
                projectId
              }
              volumeId
            }
          }
        }
      }
    }
    pageInfo {
      endCursor
      hasNextPage
      hasPreviousPage
      startCursor
    }
  }
}
